      const rc = await conTope(swRead('/marketdata/v1/chains', { symbol: sym, contractType: p.direccion === 'PUT' ? 'PUT' : 'CALL', strike: k, fromDate: exp, toDate: exp }), 8000, 'sin bid');
      if (rc.status >= 400 || swMensajeError(rc)) return null;
